/** The date line that closes the text, above the signatures. Version 1 dated the contract in its opening instead. */
const CONTRACT_CLOSING_AR =
  "تحريرًا في   ( {{CONTRACT_DATE}} )   بمدينة ( {{COMPANY_CITY}} )";

/**
 * The two signature columns.
 *
 * Phoenix types the NAMES and the national id, because it knows them and a typed name is not a
 * signature. It never types on a line whose label is التوقيع — those keep the paper form's own
 * dotted rule, because a printed signature is not one.
 */
const CONTRACT_SIGNATURE_COLUMNS_AR = [
  {
    headingAr: "الطرف الأول — الشركة",
    fieldsAr: [
      "الاسم / {{CONTRACT_SIGNATORY}}",
      "الصفة / {{CONTRACT_SIGNATORY_TITLE}}",
      "التوقيع والختم / ..................................",
    ],
  },
  {
    headingAr: "الطرف الثاني — العامل",
    fieldsAr: [
      "الاسم / {{EMPLOYEE_NAME}}",
      "الرقم القومي / {{NATIONAL_ID}}",
      "التوقيع / ..................................",
      "توقيع باستلام نسخة / ..................................",
    ],
  },
] as const;

/**
 * The running footer.
 *
 * The source document ends it with "صفحة N من M". That is dropped deliberately, not overlooked:
 * page numbering in print needs `@page` margin boxes, which Chrome does not implement, and the
 * browser's own print dialog can add page numbers if a reader wants them. Printing a wrong number
 * would be worse than printing none.
 */
const CONTRACT_FOOTER_AR = "{{COMPANY_NAME}} — {{COMPANY_LEGAL_FORM}}   ·   عقد عمل محدد المدة";

export const CONTRACT_TEMPLATE_V2: ContractTemplate = {
  id: "contract-v2",
  version: 2,
  layout: "banded",
  titleAr: CONTRACT_TITLE_AR,
  subtitleAr: CONTRACT_SUBTITLE_AR,
  openingAr: null,
  firstPartyHeadingAr: FIRST_PARTY_HEADING_AR,
  firstPartyLinesAr: FIRST_PARTY_LINES_AR,
  secondPartyHeadingAr: SECOND_PARTY_HEADING_AR,
  secondPartyLinesAr: SECOND_PARTY_LINES_AR,
  preambleHeadingAr: CONTRACT_PREAMBLE_HEADING_AR,
  preambleAr: CONTRACT_PREAMBLE_AR,
  articles: CONTRACT_ARTICLES_AR,
  closingAr: CONTRACT_CLOSING_AR,
  signatureColumns: CONTRACT_SIGNATURE_COLUMNS_AR.map((column) => ({
    headingAr: column.headingAr,
    fieldsAr: column.fieldsAr,
  })),
  footerAr: CONTRACT_FOOTER_AR,
};
